#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int P1_CONST=998244353, P2_CONST=1e9+7, B_CONST=1e6;
vector<int> seqs_arr[7];
int prefix_sum_arr[7];
long long total_nums, order_idx, total_ans;

void build_sequences(int start, int depth) {
    ++order_idx;
    seqs_arr[depth].push_back((order_idx - start + P1_CONST) % P1_CONST);
    (prefix_sum_arr[depth] += seqs_arr[depth].back()) %= P2_CONST;
    if (depth == 6) return;
    for (int digit=0; digit<=9; ++digit) {
        build_sequences(start*10 + digit, depth+1);
    }
}

void process(long long x) {
    if (x > total_nums) return;
    if (x*B_CONST + B_CONST - 1 <= total_nums && x*B_CONST*10 > total_nums) {
        long long temp_order = order_idx;
        for (int i=0, mult=1; i<=6; ++i, mult*=10) {
            int size=seqs_arr[i].size();
            int delta=((temp_order - x*mult) % P1_CONST + P1_CONST) % P1_CONST;
            int pos=lower_bound(seqs_arr[i].begin(), seqs_arr[i].end(), P1_CONST - delta) - seqs_arr[i].begin();
            total_ans = (total_ans + 1LL*delta*size + prefix_sum_arr[i]) % P2_CONST;
            total_ans = (total_ans - 1LL*(size - pos)*P1_CONST + P2_CONST) % P2_CONST;
            order_idx += size;
        }
        return;
    }
    ++order_idx;
    total_ans = (total_ans + ((order_idx - x) % P1_CONST + P1_CONST) % P1_CONST) % P2_CONST;
    for (int digit=0; digit<=9; ++digit) {
        process(x*10 + digit);
    }
}

int main() {
    long long n_value;
    cin >> n_value;
    total_nums = n_value;
    build_sequences(0,0);
    order_idx=0;
    for (int i=0; i<=6; ++i) sort(seqs_arr[i].begin(), seqs_arr[i].end());
    for (int i=1; i<=9; ++i) process(i);
    cout << total_ans;
    return 0;
}
